import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.Wx1CEKvH.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/faq/"}],["meta",{"property":"og:title","content":"常见问题 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"zh-hans/faq/index.md","filePath":"zh-hans/faq/index.md"}'),n={name:"zh-hans/faq/index.md"};function i(h,a,d,s,l,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="支持哪些游戏" tabindex="-1">支持哪些游戏？ <a class="header-anchor" href="#支持哪些游戏" aria-label="Permalink to &quot;支持哪些游戏？&quot;">​</a></h2><p>《怪物猎人：荒野》《崛起＋曙光》和《世界＋冰原》。在首页选好游戏，就能查看对应的资料。</p><h2 id="现在可以下载吗" tabindex="-1">现在可以下载吗？ <a class="header-anchor" href="#现在可以下载吗" aria-label="Permalink to &quot;现在可以下载吗？&quot;">​</a></h2><p>还不行。iOS、Android 和鸿蒙版都还在开发，暂时没有公开的商店页面。上线后，我们会把链接放在<a href="./../#download">下载页面</a>。</p><h2 id="没有网络能用吗" tabindex="-1">没有网络能用吗？ <a class="header-anchor" href="#没有网络能用吗" aria-label="Permalink to &quot;没有网络能用吗？&quot;">​</a></h2><p>可以。图鉴资料已经放在应用里，不联网也能查资料、搜索、收藏和找配装。只有打开外部网站、下载应用更新时才需要网络。</p><h2 id="配装器能做什么" tabindex="-1">配装器能做什么？ <a class="header-anchor" href="#配装器能做什么" aria-label="Permalink to &quot;配装器能做什么？&quot;">​</a></h2><p>选好想要的技能和等级，指定想保留或不想用的装备，就能搜索合适的防具组合。还可以填上自己有多少装饰品，让结果按你的库存来配。《崛起》也支持使用你已有的护石和怪异炼化防具。</p><p>能找到什么配装，取决于游戏资料和你设的条件。配装器目前不计算伤害。</p><h2 id="支持哪些语言" tabindex="-1">支持哪些语言？ <a class="header-anchor" href="#支持哪些语言" aria-label="Permalink to &quot;支持哪些语言？&quot;">​</a></h2><p>简体中文、繁体中文、英语和日语。有些内容还没翻译好，会先显示英文。网站截图会跟着页面语言切换，应用内也能自己选语言。</p><h2 id="这是-capcom-官方应用吗" tabindex="-1">这是 CAPCOM 官方应用吗？ <a class="header-anchor" href="#这是-capcom-官方应用吗" aria-label="Permalink to &quot;这是 CAPCOM 官方应用吗？&quot;">​</a></h2><p>不是。这是玩家独立制作的非商业应用，与 CAPCOM 没有关联，也没有得到其认可或支持。Monster Hunter 的游戏图片和数据归 CAPCOM Co., Ltd. 所有。</p><h2 id="怎么帮忙完善图鉴" tabindex="-1">怎么帮忙完善图鉴？ <a class="header-anchor" href="#怎么帮忙完善图鉴" aria-label="Permalink to &quot;怎么帮忙完善图鉴？&quot;">​</a></h2><p>可以帮忙核对资料或检查翻译，具体见<a href="./../others/">关于图鉴</a>。如果发现数据不对，记下是哪款游戏、哪个怪物或装备出了问题，再附上能核对的出处，会更方便我们查证。</p>',16)])])}const u=e(n,[["render",i]]);export{f as __pageData,u as default};
